-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["The method correctly projects fixed assets at $14 million since all assets scale with sales","Spare capacity absorbs some growth without proportional fixed asset increases, overstating needs","The method understates needs because capacity constraints require building entirely new plants","Fixed assets should never be included in the percentage-of-sales projection method"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (B): At 85% capacity utilization, approximately 15% spare capacity can absorb additional volume before expansion is needed (AICPA AT-C Section 301). Fixed assets increase in lumpy increments rather than proportionally, so the percentage-of-sales method overstates required capital expenditure.
