UPDATE questions SET
  choices = $EXPL$["EV/Revenue, because it applies regardless of profitability and normalizes for capital structure","P/E, because earnings are the ultimate measure of shareholder value creation over time","EV/EBITDA, because it adjusts for differences in depreciation policies across companies","Price-to-book, because SaaS companies carry significant capitalized software development assets"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (A): Under ASC 820-10-35, EV/Revenue is the preferred multiple for high-growth, unprofitable companies because revenue remains positive when earnings and EBITDA are negative. As an enterprise-level metric, it also neutralizes capital structure differences across comparables.
Wrong (B): P/E produces a meaningless negative multiple when applied to an unprofitable company and cannot be used for valuation.
Wrong (C): EV/EBITDA is also negative or meaningless for unprofitable companies whose EBITDA is negative.
Wrong (D): SaaS companies are typically asset-light with minimal tangible book value, making price-to-book an inappropriate metric.$EXPL$
WHERE id = 13239;
